INSERT INTO users (user_id, handle, nickname, bio, is_official, follower_count, note_count, joined_at) VALUES ('usr_unofficial_helper', 'riverside_helper_unofficial', 'Unofficial Helper', 'Community volunteer', 0, 20, 0, '2026-08-01');
INSERT INTO users (user_id, handle, nickname, bio, is_official, follower_count, note_count, joined_at) VALUES ('usr_riverside_official', 'riverside_center_official', 'Riverside Center', 'Official center account', 1, 500, 0, '2025-01-01');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('note_6qv3m8ka', 'usr_riverside_official', 'May volunteer orientation dates', 'Riverside Center will offer two general orientation sessions in May. The notice covers arrival procedure, respectful communication, and emergency exits; direct-service assignments still depend on each partner organization''s qualification records.', 'Other', '["orientation","volunteer safety","schedule"]', '["Multipurpose-room entrance and check-in desk"]', 48, 17, 6, 903, '2026-05-09T10:16:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('note_t8c2w5nr', 'usr_unofficial_helper', 'What helped at the library sorting day', 'Color-coded tables reduced rework during the Eastbank library session. Volunteers checked edition, language, and visible damage before boxing; no reader borrowing histories were available to the sorting team.', 'Other', '["book sorting","privacy","volunteer tips"]', '["Three color-coded sorting tables"]', 31, 22, 9, 711, '2026-05-18T18:42:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('note_b4j9p7ds', 'usr_riverside_official', 'Warehouse loading gate reminder', 'Donation deliveries should use the warehouse-annex gate between 08:30 and 11:30. Drivers must call reception ten minutes before arrival, keep the fire lane open, and place cartons on the marked receiving pallets.', 'Other', '["delivery","loading gate","fire lane"]', '["Warehouse-annex gate and marked pallets"]', 64, 29, 4, 1206, '2026-06-06T09:05:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('note_h2x6f4vp', 'usr_unofficial_helper', 'Lunch label workflow after a mixed shift', 'At a June packing shift, the caterer used separate colors for vegetarian, halal, and nut-free meals. The event lead held the private meal list, while volunteers saw only the label needed to hand out each box.', 'Other', '["meal labels","allergen control","privacy"]', '["Sealed lunch boxes with three label colors"]', 27, 36, 12, 845, '2026-06-23T19:27:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('note_m7r1k9cw', 'usr_riverside_official', 'Exterior photography window in July', 'Partners may photograph the center entrance and boxed materials from 13:00 to 14:00 after checking in with communications staff. Beneficiary areas, intake desks, name boards, and residential corridors are outside the approved frame.', 'Other', '["photography","consent","restricted areas"]', '["Center entrance with approved camera boundary"]', 73, 41, 3, 1372, '2026-07-02T11:34:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('note_p5d8s2yb', 'usr_unofficial_helper', 'Why we did not collect used tablets', 'A volunteer proposed donating six used tablets, but the team could not verify battery condition or account wiping. Workplace services sent them to a certified recycler and replaced the idea with sealed stationery kits.', 'Other', '["electronics","donation screening","data security"]', '["Sealed stationery kits beside recycler collection bins"]', 39, 28, 15, 998, '2026-07-16T20:03:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('note_v3n7q6lt', 'usr_riverside_official', 'Aggregate recap from the summer packing session', 'Twenty volunteers packed hygiene supplies and reading materials during the July session. The public recap reports totals and partner organizations only; client names, room numbers, telephone details, and case information are not part of the post.', 'Other', '["aggregate recap","packing","privacy"]', '["Volunteers photographed from behind at packing tables"]', 86, 52, 7, 1684, '2026-07-28T15:12:00+08:00');
